import React from 'react';
import './Header.css';

function Header({ cantidadProductos, toggleCarrito }) {
  // Función para desplazarse a una sección específica
  const scrollToSection = (e, sectionId) => {
    e.preventDefault();

    if (sectionId === 'inicio') {
      window.scrollTo({
        top: 0,
        behavior: 'smooth'
      });
    } else {
      const section = document.getElementById(sectionId);
      if (section) {
        section.scrollIntoView({ behavior: 'smooth' });
      }
    }
  };

  return (
    <header className="header">
      <div className="logo">
        <h1>DeviiFarma</h1>
        <span className="slogan">Tu salud, nuestra prioridad</span>
      </div>

      <nav className="navegacion">
        <ul>
          <li><a href="#inicio" onClick={(e) => scrollToSection(e, 'inicio')}>Inicio</a></li>
          <li><a href="#productos" onClick={(e) => scrollToSection(e, 'productos')}>Productos</a></li>
          <li><a href="#ofertas" onClick={(e) => scrollToSection(e, 'ofertas')}>Ofertas</a></li>
          <li><a href="#contacto" onClick={(e) => scrollToSection(e, 'contacto')}>Contacto</a></li>
        </ul>
      </nav>

      <div className="carrito-icono" onClick={toggleCarrito}>
        <i className="fas fa-shopping-cart"></i>
        {cantidadProductos > 0 && <span className="contador">{cantidadProductos}</span>}
      </div>
    </header>
  );
}

export default Header;
